CREATE TYPE "SupportReleaseStatus" AS ENUM ('PLANNED','IN_DEVELOPMENT','READY_FOR_PREVIEW','PREVIEW_VALIDATION','BLOCKED','READY_FOR_PRODUCTION','PRODUCTION','ROLLED_BACK','ARCHIVED');
CREATE TYPE "SupportReleaseEnvironment" AS ENUM ('LOCAL','PREVIEW','PRODUCTION');
CREATE TYPE "SupportValidationResult" AS ENUM ('NOT_STARTED','PASS','FAIL','BLOCKED','NOT_APPLICABLE');
CREATE TABLE "SupportRelease" ("id" UUID NOT NULL,"version" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"status" "SupportReleaseStatus" NOT NULL DEFAULT 'PLANNED',"environment" "SupportReleaseEnvironment" NOT NULL DEFAULT 'PREVIEW',"releaseNotes" TEXT,"validationNotes" TEXT,"backendCommit" TEXT,"frontendCommit" TEXT,"supportCommit" TEXT,"railwayUrl" TEXT,"vercelPreviewUrl" TEXT,"productionUrl" TEXT,"versionNumber" INTEGER NOT NULL DEFAULT 1,"createdByUserId" UUID NOT NULL,"updatedByUserId" UUID NOT NULL,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(6) NOT NULL,"previewDeployedAt" TIMESTAMPTZ(6),"productionDeployedAt" TIMESTAMPTZ(6),CONSTRAINT "SupportRelease_pkey" PRIMARY KEY("id"));
CREATE TABLE "SupportReleaseValidation" ("id" UUID NOT NULL,"releaseId" UUID NOT NULL,"name" TEXT NOT NULL,"result" "SupportValidationResult" NOT NULL DEFAULT 'NOT_STARTED',"notes" TEXT,"sortOrder" INTEGER NOT NULL DEFAULT 0,"updatedByUserId" UUID NOT NULL,"updatedAt" TIMESTAMPTZ(6) NOT NULL,CONSTRAINT "SupportReleaseValidation_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "SupportRelease_version_key" ON "SupportRelease"("version"); CREATE INDEX "SupportRelease_status_updatedAt_idx" ON "SupportRelease"("status","updatedAt"); CREATE UNIQUE INDEX "SupportReleaseValidation_releaseId_name_key" ON "SupportReleaseValidation"("releaseId","name"); CREATE INDEX "SupportReleaseValidation_releaseId_sortOrder_idx" ON "SupportReleaseValidation"("releaseId","sortOrder");
ALTER TABLE "SupportRelease" ADD CONSTRAINT "SupportRelease_createdByUserId_fkey" FOREIGN KEY("createdByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupportRelease" ADD CONSTRAINT "SupportRelease_updatedByUserId_fkey" FOREIGN KEY("updatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "SupportReleaseValidation" ADD CONSTRAINT "SupportReleaseValidation_releaseId_fkey" FOREIGN KEY("releaseId") REFERENCES "SupportRelease"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SupportReleaseValidation" ADD CONSTRAINT "SupportReleaseValidation_updatedByUserId_fkey" FOREIGN KEY("updatedByUserId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
